+			}
+
+			prefixes, err := r.getAllowedPrefixes(context.Background(), imageConfig)
+			if tc.expectedError {
+				if err == nil {
+					t.Errorf("expected error but got none")
+				}
+				return
+			}
+
+			if err != nil {
+				t.Errorf("unexpected error: %v", err)
