diff --git a/pkg/image/apiserver/registry/imagestreamimport/transport.go b/pkg/image/apiserver/registry/imagestreamimport/transport.go
new file mode 100644
index 0000000000..0094881289
--- /dev/null
+++ b/pkg/image/apiserver/registry/imagestreamimport/transport.go
@@ -0,0 +1,63 @@
+package imagestreamimport
+
+import (
+	"context"
+	"errors"
+	"net/http"
+	"net/netip"
+
+	"github.com/openshift/openshift-apiserver/pkg/image/apis/image/validation"
+)
+
+// hostContactCheck is a function that checks whether it's safe to contact a
+// given host based on blocked and allowed IP prefix lists.
+type hostContactCheck func(context.Context, string, []netip.Prefix, []netip.Prefix) error
+
+// RestrictedTransport is an http.RoundTripper.
+var _ http.RoundTripper = &RestrictedTransport{}
+
+// RestrictedTransport restricts requests to certain IP ranges. It is meant to
+// avoid doing requests to addresses the registry should not be allowed to
+// reach.
+type RestrictedTransport struct {
+	wrapped           http.RoundTripper
+	blocked           []netip.Prefix
+	allowed           []netip.Prefix
+	shouldContactHost hostContactCheck
+}
+
+// RoundTrip implements the http.RoundTripper interface. If the IP is blocked
+// an error is returned, if not then it delegates to the wrapped RoundTripper.
+func (r *RestrictedTransport) RoundTrip(req *http.Request) (*http.Response, error) {
+	if r.wrapped == nil {
+		return nil, errors.New("no wrapped round tripper")
+	}
+
+	if r.shouldContactHost == nil {
+		return nil, errors.New("nil validation function")
+	}
+
+	if req == nil || req.URL == nil {
+		return nil, errors.New("nil request or url")
+	}
+
+	host := req.URL.Hostname()
+	if err := r.shouldContactHost(req.Context(), host, r.blocked, r.allowed); err != nil {
+		return nil, err
+	}
+
+	return r.wrapped.RoundTrip(req)
+}
+
+// NewRestrictedTransport creates a new RestrictedTransport that wraps the
+// given http.RoundTripper and blocks requests to the given list of CIDR ranges.
+// IPs in the allowed list bypass all checks; IPs not in allowed are checked
+// against loopback, link-local, and the blocked list.
+func NewRestrictedTransport(wrapped http.RoundTripper, blocked, allowed []netip.Prefix) *RestrictedTransport {
+	return &RestrictedTransport{
+		wrapped:           wrapped,
+		blocked:           blocked,
+		allowed:           allowed,
+		shouldContactHost: validation.ShouldContactHost,
+	}
+}
diff --git a/pkg/image/apiserver/registry/imagestreamimport/transport_test.go b/pkg/image/apiserver/registry/imagestreamimport/transport_test.go
new file mode 100644
index 0000000000..5a282601c6
--- /dev/null
+++ b/pkg/image/apiserver/registry/imagestreamimport/transport_test.go
@@ -0,0 +1,159 @@
+package imagestreamimport
+
+import (
+	"context"
+	"errors"
+	"net/http"
+	"net/netip"
+	"strings"
+	"testing"
+)
+
+// mockRoundTripper is a mock implementation of http.RoundTripper for testing
+type mockRoundTripper struct {
+	responses []*http.Response
+	callCount int
+	err       error
+}
+
+func (m *mockRoundTripper) RoundTrip(req *http.Request) (*http.Response, error) {
+	if m.err != nil {
+		return nil, m.err
+	}
+
+	if len(m.responses) > 0 {
+		if m.callCount >= len(m.responses) {
+			return nil, errors.New("mock: unexpected call to RoundTrip")
+		}
+		resp := m.responses[m.callCount]
+		m.callCount++
+		return resp, nil
+	}
+
+	// Default response when no responses configured
+	return &http.Response{
+		StatusCode: 200,
+		Body:       http.NoBody,
+		Request:    req,
+	}, nil
+}
+
+func TestRestrictedTransport(t *testing.T) {
+	mockShouldContactHost := func(hostResults map[string]error) hostContactCheck {
+		return func(_ context.Context, h string, _, _ []netip.Prefix) error {
+			return hostResults[h]
+		}
+	}
+
+	testCases := []struct {
+		name        string
+		url         string
+		hostResults map[string]error
+		errContains string
+		mockError   error
+		responses   []*http.Response
+	}{
+		{
+			name:        "nil shouldContactHost returns error",
+			url:         "http://safe.example.com:5000/v2/",
+			errContains: "nil validation function",
+		},
+		{
+			name: "shouldContactHost blocks request",
+			url:  "http://blocked.local:5000/v2/",
+			hostResults: map[string]error{
+				"blocked.local": errors.New("blocked by policy"),
+			},
+			errContains: "blocked by policy",
+		},
+		{
+			name:        "shouldContactHost allows request",
+			url:         "http://allowed.example.com:5000/v2/",
+			hostResults: map[string]error{},
+		},
+		{
+			name: "shouldContactHost allows initial host but blocks redirect",
+			url:  "http://safe.example.com/v2/",
+			responses: []*http.Response{
+				{
+					StatusCode: 302,
+					Header: http.Header{
+						"Location": []string{"http://evil.local/v2/"},
+					},
+					Body: http.NoBody,
+				},
+			},
+			hostResults: map[string]error{
+				"safe.example.com": nil,
+				"evil.local":       errors.New("redirect blocked"),
+			},
+			errContains: "redirect blocked",
+		},
+		{
+			name: "shouldContactHost allows redirect chain",
+			url:  "http://safe1.example.com/v2/",
+			responses: []*http.Response{
+				{
+					StatusCode: 302,
+					Header: http.Header{
+						"Location": []string{"http://safe2.example.com/v2/"},
+					},
+					Body: http.NoBody,
+				},
+				{
+					StatusCode: 200,
+					Body:       http.NoBody,
+				},
+			},
+			hostResults: map[string]error{
+				"safe1.example.com": nil,
+				"safe2.example.com": nil,
+			},
+		},
+		{
+			name:        "propagate wrapped transport error",
+			url:         "http://safe.local:5000/v2/",
+			hostResults: map[string]error{},
+			mockError:   errors.New("connection refused"),
+			errContains: "connection refused",
+		},
+	}
+
+	for _, tc := range testCases {
+		t.Run(tc.name, func(t *testing.T) {
+			mock := &mockRoundTripper{
+				responses: tc.responses,
+				err:       tc.mockError,
+			}
+
+			transport := NewRestrictedTransport(mock, nil, nil)
+			transport.shouldContactHost = nil
+			if tc.hostResults != nil {
+				transport.shouldContactHost = mockShouldContactHost(tc.hostResults)
+			}
+
+			client := &http.Client{Transport: transport}
+			resp, err := client.Get(tc.url)
+			defer func() {
+				if resp != nil && resp.Body != nil {
+					resp.Body.Close()
+				}
+			}()
+
+			if tc.errContains != "" {
+				if err == nil {
+					t.Errorf("expected error but got none")
+					return
+				}
+				if !strings.Contains(err.Error(), tc.errContains) {
+					t.Errorf("expected error to contain %q, got: %v", tc.errContains, err)
+				}
+				return
+			}
+
+			if err != nil {
+				t.Errorf("unexpected error: %v", err)
+			}
+		})
+	}
+}
